#if DEBUG
import CoreGraphics
import Foundation

// MARK: Fixture format
//
// A labelled structure benchmark, in the sketch corpus's style (`SketchBenchmark.swift`): things already on a screen and
// one batch of new sketches, drawn from `SketchSamples`' strokes with seeded jitter, stored as JSON beside the sketch
// fixtures (`LayerTests/Fixtures/structure-*.json`) and generated by `Tools/SketchBenchmarkHarness`. The sketch corpus's
// loader skips them. Used by `StructureFixtureTests` in the simulator and by the macOS harness's `structure` mode.

/// One batch of sketches on a screen, and the structure the pass should make of it.
struct StructureFixture: Codable, Sendable, Identifiable {
    enum Variant: String, Codable, Sendable { case clean, jittered, noisy, nearMiss }

    /// "structure-row_clean_1"
    var id: String
    /// What it should become: "row", "column", "grid", "card" or "none".
    var label: String
    var variant: Variant
    var screenSize: [Double]
    /// On the screen before the batch.
    var existing: [SketchFixture.ExistingFixture]
    /// One batch, in order: each sketch's strokes, each stroke's points as [x, y].
    var sketches: [[[[Double]]]]
    /// "apply", "offer" or "none".
    var expected: String
}

extension StructureFixture {
    /// Whether what the pass found is what this fixture expects. A clean or jittered fixture becomes its structure with
    /// its decision; a near miss never groups (its decision is none); a noisy one is never the wrong structure: the expected one, or none.
    func isAsExpected(label found: String, decision: String) -> Bool {
        switch variant {
        case .clean, .jittered: found == label && decision == expected
        // A card that holds only what it encloses is no grouping: what matters is that the pass makes nothing of it.
        case .nearMiss: decision == "none" && (found == "none" || found == label)
        case .noisy: found == label || found == "none"
        }
    }
}

enum StructureBenchmark {
    static func load(from directory: URL) throws -> [StructureFixture] {
        let files = try FileManager.default.contentsOfDirectory(at: directory, includingPropertiesForKeys: nil)
            .filter { $0.pathExtension == "json" && $0.lastPathComponent.hasPrefix("structure-") }
            .sorted { $0.lastPathComponent < $1.lastPathComponent }
        let decoder = JSONDecoder()
        return try files.map { try decoder.decode(StructureFixture.self, from: Data(contentsOf: $0)) }
    }

    /// The screen's content with the batch placed, the nodes the batch made, and which of them are cards that took something.
    static func place(_ fixture: StructureFixture) -> (content: TreeContent, batch: Set<UUID>, cards: [UUID]) {
        let size = CGSize(width: fixture.screenSize[0], height: fixture.screenSize[1])
        var screen = TreeScreen(name: "Screen", origin: .zero, scale: 1, deviceID: nil)
        screen.root.children = fixture.existing.map { existing in
            var node = LayerNode(kind: existing.kind)
            node.frame = CGRect(x: existing.frame[0], y: existing.frame[1], width: existing.frame[2], height: existing.frame[3])
            node.content.text = existing.kind.placeholder
            node.isLocked = existing.locked ?? false
            return node
        }
        var content = TreeContent()
        content.screens = [screen]

        var batch: Set<UUID> = []
        var cards: [UUID] = []
        for strokes in fixture.sketches {
            let paths = strokes.map { $0.map { CGPoint(x: $0[0], y: $0[1]) } }
            guard let observation = SketchAnalyzer.observe(SketchSamples.strokes(paths)) else { continue }
            let root = content.screens[0].root
            let placed = root.children.filter { !$0.isHidden }
                .map { ExistingElement(kind: $0.kind, frame: $0.frame) }
            let request = SketchRequest(observation: observation,
                                        placement: .onScreen(local: observation.bounds, existing: placed, size: size),
                                        strokes: paths)
            guard case .element(let kind) = RuleInterpreter().reading(for: request) else { continue }
            let confidence = request.scoredReadings.first { $0.reading == .element(kind) }?.score ?? 1
            guard let made = SketchedNode.make(kind, sketch: observation.bounds, in: content, index: TreeIndex(content),
                                               confidence: confidence, decidedBy: .rules)
            else { continue }
            content.screens[0].root = SketchedNode.inserting(made, into: root)
            batch.insert(made.node.id)
            if !made.takes.isEmpty { cards.append(made.node.id) }
        }

        return (content, batch, cards)
    }

    /// Each sketch is read by the rules, placed with `SketchedNode` on a free root built from `existing`, then the pass
    /// runs over the batch. Returns the structure kind found ("none" when there isn't one), the decision, and the pass's
    /// time. A batch that made a card round something is read by what the pass makes of the card's inside, labelled
    /// "card"; otherwise the pass runs over the screen's root, and the last decision (the outermost) is the answer.
    static func run(_ fixture: StructureFixture) -> (label: String, decision: String, passSeconds: Double) {
        let (content, batch, cards) = place(fixture)
        let tokens = content.settings.tokens
        let root = content.screens[0].root
        var decisions: [StructureInference.Decision] = []
        let start = ContinuousClock.now
        if cards.isEmpty {
            decisions = StructureInference.infer(in: root, new: batch, tokens: tokens)
        } else {
            for card in root.children where cards.contains(card.id) {
                decisions += StructureInference.infer(in: card, new: Set(card.children.map(\.id)), tokens: tokens, depth: 1)
            }
        }
        let seconds = (ContinuousClock.now - start).secondsValue

        let found = decisions.last
        let decision: String
        switch found {
        case .apply: decision = "apply"
        case .offer: decision = "offer"
        case nil: decision = "none"
        }
        guard !cards.isEmpty else { return (label(of: found), decision, seconds) }
        return ("card", decision, seconds)
    }

    private static func label(of decision: StructureInference.Decision?) -> String {
        let structure: StructureInference.Structure
        switch decision {
        case .apply(let found), .offer(let found): structure = found
        case nil: return "none"
        }
        switch structure.kind {
        case .row: return "row"
        case .column, .cardColumn: return "column"
        case .grid: return "grid"
        }
    }
}
#endif
